package modules

import (
	"context"
	"crypto/sha256"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"slices"
	"strings"
)

// No YAML is interpreted here. Generated native settings identify devices;
// generated filenames identify configurations removed from physical links.
type netplanGeneratedFiles map[string][]networkdSetting

type netplanRestoreData struct {
	previousContentsSHA256        string
	previousExisted               bool
	DevicesToRemove               []string `json:"virtual_devices_to_remove_after_file_change,omitempty"`
	DevicesToRemoveOnRestore      []string `json:"virtual_devices_to_remove_on_restore,omitempty"`
	NetworkFilesToRemove          []string `json:"generated_network_files_removed_after_file_change,omitempty"`
	NetworkFilesToRemoveOnRestore []string `json:"generated_network_files_removed_on_restore,omitempty"`
}

func readNetplanGeneratedFiles(directory string) (netplanGeneratedFiles, error) {
	files := netplanGeneratedFiles{}
	entries, err := os.ReadDir(directory)
	if os.IsNotExist(err) {
		return files, nil
	}
	if err != nil {
		return nil, err
	}
	for _, entry := range entries {
		name := entry.Name()
		if !strings.HasPrefix(name, "10-netplan-") || (!strings.HasSuffix(name, ".netdev") && !strings.HasSuffix(name, ".network")) {
			continue
		}
		text, err := readNetworkdDeclaration(filepath.Join(directory, name))
		if err != nil {
			return nil, err
		}
		files[name] = networkdSettings(text)
	}
	return files, nil
}

func netplanDeviceSettings(files netplanGeneratedFiles) (map[string][]networkdSetting, error) {
	devices := map[string][]networkdSetting{}
	for file, settings := range files {
		if !strings.HasSuffix(file, ".netdev") {
			continue
		}
		names, err := networkdDeclaredDevices(settings, false)
		if err != nil {
			return nil, err
		}
		for _, name := range names {
			if previous, exists := devices[name]; exists && !reflect.DeepEqual(previous, settings) {
				return nil, fmt.Errorf("The files generated by Netplan contain conflicting definitions for network device %s.", name)
			}
			devices[name] = settings
		}
	}
	return devices, nil
}

func planNetplanDevices(destination string, before, after netplanGeneratedFiles) (netplanRestoreData, error) {
	data := netplanRestoreData{}
	oldDevices, err := netplanDeviceSettings(before)
	if err != nil {
		return data, netplanCheckFailure(destination, err)
	}
	newDevices, err := netplanDeviceSettings(after)
	if err != nil {
		return data, netplanCheckFailure(destination, err)
	}
	for name, settings := range newDevices {
		previous, declared := oldDevices[name]
		if declared && !reflect.DeepEqual(previous, settings) {
			return data, fmt.Errorf("Cannot change the settings of network device %s in %s: systemd-networkd applies the settings only when creating the device, so a restore could not undo the change; first remove the device definition from the Netplan file and apply the file, then add the device definition with the new settings.", name, destination)
		}
		exists, err := networkdDeviceExists(name)
		if err != nil {
			return data, netplanCheckFailure(destination, err)
		}
		if exists {
			if !declared {
				return data, fmt.Errorf("Cannot add %s: network device %s already exists and was not created by Netplan.", destination, name)
			}
		} else if !declared {
			data.DevicesToRemoveOnRestore = append(data.DevicesToRemoveOnRestore, name)
		}
	}
	for name := range oldDevices {
		if _, exists := newDevices[name]; !exists {
			data.DevicesToRemove = append(data.DevicesToRemove, name)
		}
	}
	// One end deletes a veth's peer too. Retained or pre-existing peers must
	// never be deleted indirectly through an otherwise removable end.
	for _, devices := range []struct {
		files    netplanGeneratedFiles
		removals *[]string
	}{{before, &data.DevicesToRemove}, {after, &data.DevicesToRemoveOnRestore}} {
		for file, settings := range devices.files {
			if !strings.HasSuffix(file, ".netdev") {
				continue
			}
			names, err := networkdDeclaredDevices(settings, false)
			if err != nil {
				return data, netplanCheckFailure(destination, err)
			}
			if len(names) == 2 && (!slices.Contains(*devices.removals, names[0]) || !slices.Contains(*devices.removals, names[1])) {
				*devices.removals = slices.DeleteFunc(*devices.removals, func(name string) bool { return slices.Contains(names, name) })
			}
		}
	}
	for name, settings := range before {
		if !strings.HasSuffix(name, ".network") {
			continue
		}
		if proposed, exists := after[name]; !exists {
			data.NetworkFilesToRemove = append(data.NetworkFilesToRemove, name)
		} else if !reflect.DeepEqual(netplanMatchSettings(settings), netplanMatchSettings(proposed)) {
			definition := strings.TrimSuffix(strings.TrimPrefix(name, "10-netplan-"), ".network")
			return data, fmt.Errorf("Cannot change the network interfaces matched by Netplan definition %s in %s: MMX cannot determine which interface would lose configuration; give the definition a new name, or remove the definition and apply the file before adding the definition again.", definition, destination)
		}
	}
	for name := range after {
		if _, exists := before[name]; !exists && strings.HasSuffix(name, ".network") {
			data.NetworkFilesToRemoveOnRestore = append(data.NetworkFilesToRemoveOnRestore, name)
		}
	}
	for _, names := range [][]string{data.DevicesToRemove, data.DevicesToRemoveOnRestore, data.NetworkFilesToRemove, data.NetworkFilesToRemoveOnRestore} {
		slices.Sort(names)
	}
	return data, nil
}

func netplanMatchSettings(settings []networkdSetting) []networkdSetting {
	var matches []networkdSetting
	for _, setting := range settings {
		if setting.section == "Match" {
			matches = append(matches, setting)
		}
	}
	return matches
}

func netplanCheckFailure(destination string, err error) error {
	return fmt.Errorf("Cannot check the proposed %s with Netplan: %w", destination, err)
}

// Netplan's YAML diagnostics echo a source line, which can contain secrets
// from a file unrelated to this task. Keep diagnostic messages only, including
// when capture ends before the caret. Apply and restore use the same filter.
var netplanDiagnosticLocation = regexp.MustCompile(`^/[^\r\n]+\.ya?ml(?::[0-9]+:[0-9]+)?: (?:Error|Invalid YAML)(?::| )`)
var netplanDiagnosticMessage = regexp.MustCompile(`^(?:(?:Error in network definition|Invalid YAML|Error parsing YAML): |(?:ERROR|WARNING):|\*\* \([^\r\n]+\): (?:ERROR|WARNING|CRITICAL) \*\*: )`)

func netplanDiagnosticMessages(output string) string {
	var messages []string
	lines := strings.Split(output, "\n")
	skipSource := false
	for index, line := range lines {
		if skipSource {
			skipSource = false
			continue
		}
		// A bare diagnostic can also have source context. Never retain the
		// line directly above its caret, even if it resembles a message.
		if index+1 < len(lines) && strings.TrimSpace(lines[index+1]) == "^" {
			continue
		}
		if netplanDiagnosticLocation.MatchString(line) {
			messages = append(messages, line)
			skipSource = true
		} else if netplanDiagnosticMessage.MatchString(line) {
			messages = append(messages, line)
			skipSource = strings.HasPrefix(line, "Error ") || strings.HasPrefix(line, "Invalid YAML:")
		}
	}
	return strings.Join(messages, "\n")
}

func netplanCommandFailure(output CommandOutput) error {
	if output.Error != "" {
		return fmt.Errorf("%s", output.Error)
	}
	if output.ExitCode == 0 {
		return nil
	}
	diagnostic := strings.TrimSpace(netplanDiagnosticMessages(output.StandardError) + "\n" + netplanDiagnosticMessages(output.StandardOutput))
	if diagnostic == "" {
		return fmt.Errorf("Netplan exited with code %d without an error message that MMX recognizes.", output.ExitCode)
	}
	return fmt.Errorf("%s", diagnostic)
}

// Dereference regular-file symlinks while copying: the private tree must not
// give Netplan a writable link back into the live tree. Netplan's library
// directory can contain a symlink to its generator executable.
func copyNetplanDirectory(source, destination string) error {
	resolved, err := filepath.EvalSymlinks(source)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return err
	}
	return filepath.WalkDir(resolved, func(path string, entry os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		relative, err := filepath.Rel(resolved, path)
		if err != nil {
			return err
		}
		target := filepath.Join(destination, relative)
		if entry.IsDir() {
			return os.MkdirAll(target, 0700)
		}
		info, err := os.Stat(path)
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() {
			return fmt.Errorf("Cannot copy %s for Netplan's configuration check: the path is not a regular file or directory.", path)
		}
		input, err := os.Open(path)
		if err != nil {
			return err
		}
		defer input.Close()
		output, err := os.OpenFile(target, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
		if err != nil {
			return err
		}
		_, copyError := io.Copy(output, input)
		closeError := output.Close()
		if copyError != nil {
			return copyError
		}
		return closeError
	})
}

func planNetplanChange(ctx context.Context, run Runtime, destination, proposed string, absent bool) (data netplanRestoreData, err error) {
	var tree string
	defer func() {
		if err != nil {
			message := err.Error()
			if tree != "" {
				message = strings.ReplaceAll(message, tree+"/", "/")
			}
			err = fmt.Errorf("%s", message)
		}
	}()
	// generate can invoke the live systemd generator on some tool versions.
	// Treat it as a mutation, though the proposed YAML stays in the copy.
	if err = run.Mutation(destination); err != nil {
		return data, netplanCheckFailure(destination, err)
	}
	tree, remove, err := run.makePrivateTaskDirectory("netplan_file", nil, nil)
	if err != nil {
		return data, netplanCheckFailure(destination, err)
	}
	defer remove()
	for index, directory := range netplanDirectories {
		if err = copyNetplanDirectory(directory, filepath.Join(tree, []string{"etc/netplan", "run/netplan", "lib/netplan"}[index])); err != nil {
			return data, netplanCheckFailure(destination, err)
		}
	}
	candidate := filepath.Join(tree, "etc/netplan", filepath.Base(destination))
	previous, readError := os.ReadFile(candidate)
	if readError != nil && !os.IsNotExist(readError) {
		return data, netplanCheckFailure(destination, readError)
	}
	previousExisted := readError == nil
	generate := func() error {
		output := run.RunCommandThatChangesTheNode(ctx, []string{"netplan", "generate", "--root-dir", tree}, "")
		if output.Error != "" {
			return netplanCheckFailure(destination, netplanCommandFailure(output))
		}
		if err := netplanCommandFailure(output); err != nil {
			return fmt.Errorf("Netplan rejected the network configuration while checking %s: %w", destination, err)
		}
		return nil
	}
	if err = generate(); err != nil {
		return data, err
	}
	generated := filepath.Join(tree, "run/systemd/network")
	before, err := readNetplanGeneratedFiles(generated)
	if err != nil {
		return data, netplanCheckFailure(destination, err)
	}
	if absent {
		err = os.Remove(candidate)
		if os.IsNotExist(err) {
			err = nil
		}
	} else {
		err = os.MkdirAll(filepath.Dir(candidate), 0700)
		if err == nil {
			err = os.WriteFile(candidate, []byte(proposed), 0600)
		}
	}
	if err != nil {
		return data, netplanCheckFailure(destination, err)
	}
	// Remove all generated output, including a baseline NetworkManager profile,
	// so only the proposed tree decides which renderer it uses.
	for _, directory := range []string{"run/systemd/network", "run/NetworkManager", "run/udev", "run/systemd/system"} {
		if err = os.RemoveAll(filepath.Join(tree, directory)); err != nil {
			return data, netplanCheckFailure(destination, err)
		}
	}
	if err = generate(); err != nil {
		return data, err
	}
	profiles, err := os.ReadDir(filepath.Join(tree, "run/NetworkManager/system-connections"))
	if err != nil && !os.IsNotExist(err) {
		return data, netplanCheckFailure(destination, err)
	}
	if len(profiles) != 0 {
		return data, fmt.Errorf("The proposed Netplan configuration uses the NetworkManager renderer, which netplan_file does not support.")
	}
	after, err := readNetplanGeneratedFiles(generated)
	if err != nil {
		return data, netplanCheckFailure(destination, err)
	}
	data, err = planNetplanDevices(destination, before, after)
	// Device refusals already name the resource and why it cannot change.
	if err != nil {
		return data, err
	}
	data.previousExisted = previousExisted
	data.previousContentsSHA256 = fmt.Sprintf("%x", sha256.Sum256(previous))
	return data, nil
}
